/**
 * What `derive` may say, and the three ways it can prove a run cannot
 * proceed. Amends spec §3.3 (final): `Command.materialize_stage` drops
 * `stage_contract` (the storage layer already holds the compiled definition
 * and can look the contract up by `stage_key`); `materialize_unit` /
 * `revise_unit` gain `stage_key` and `inputs` — the named per-unit input map
 * — because `apply` must resolve slot bindings by input name, and
 * `input_snapshot` alone (its flattened envelopes) cannot answer "what is
 * input 'brief'".
 *
 * `StageInputSet` moves here from `compiler/select-unit-inputs.ts`, which is
 * deleted in the same PR — do not import it.
 */
import type { ArtifactEnvelope } from "../domain/execution";
import type { ArtifactId, InputFingerprint, JsonValue, RunRecordVersion, RunUnitId, StageInstanceId, UnitId, WorkOrderId } from "../domain/primitives";
import type { MaterializedRunOutput } from "../domain/run-record";
import type { StageKey, StageOutcome } from "../domain/workflow";
import type { StagePolicy } from "./snapshot";

export type StageInputSet = Readonly<Record<string, ArtifactEnvelope | readonly ArtifactEnvelope[]>>;

export type Command =
  | { readonly kind: "materialize_stage"; readonly stage_key: StageKey; readonly stage_instance_id: StageInstanceId; readonly policy: StagePolicy }
  | {
      readonly kind: "materialize_unit";
      readonly stage_key: StageKey;
      readonly stage_instance_id: StageInstanceId;
      readonly run_unit_id: RunUnitId;
      readonly unit_id: UnitId;
      readonly parameters: JsonValue;
      readonly depends_on: readonly UnitId[];
      readonly inputs: StageInputSet;
      readonly input_snapshot: readonly ArtifactEnvelope[];
      readonly input_fingerprint: InputFingerprint;
      readonly outputs: readonly MaterializedRunOutput[];
      /** Part of the stage's stored materialization fingerprint; `apply` needs it to persist the unit. */
      readonly policy: StagePolicy;
    }
  | {
      readonly kind: "revise_unit";
      readonly stage_key: StageKey;
      readonly stage_instance_id: StageInstanceId;
      readonly run_unit_id: RunUnitId;
      readonly unit_id: UnitId;
      readonly parameters: JsonValue;
      readonly inputs: StageInputSet;
      readonly input_snapshot: readonly ArtifactEnvelope[];
      readonly input_fingerprint: InputFingerprint;
    }
  | { readonly kind: "close_materialization"; readonly stage_key: StageKey; readonly stage_instance_id: StageInstanceId; readonly policy: StagePolicy }
  | { readonly kind: "mark_unit_satisfied"; readonly run_unit_id: RunUnitId }
  | { readonly kind: "start_work"; readonly work_order_id: TaskOrderId; readonly run_unit_id: RunUnitId }
  | { readonly kind: "mark_stage_succeeded"; readonly stage_instance_id: StageInstanceId }
  | { readonly kind: "complete_run"; readonly outcome: StageOutcome };

export type Contradiction =
  | { readonly kind: "unknown_dependency_at_close"; readonly stage_key: StageKey; readonly unit_id: UnitId; readonly dependency: UnitId }
  | { readonly kind: "dependency_cycle"; readonly stage_key: StageKey; readonly cycle: readonly UnitId[] }
  /** `artifact_id` is null only when the fan-out drives over a non-input binding (repository provisioning fans out over run context). */
  | { readonly kind: "malformed_driver_artifact"; readonly stage_key: StageKey; readonly artifact_id: ArtifactId | null; readonly path: string; readonly detail: string };

export interface Derivation {
  /** One atomic batch, in application order; empty = nothing to do. */
  readonly commands: readonly Command[];
}

/** What `decide_run` (storage layer) returns to the root loop. Replaces `RunDecision`. */
export type AskResult =
  | { readonly kind: "complete"; readonly outcome: StageOutcome }
  | { readonly kind: "recheck"; readonly record_version: RunRecordVersion; readonly started: readonly { readonly id: TaskOrderId; readonly run_unit_id: RunUnitId }[] }
  | { readonly kind: "wait"; readonly record_version: RunRecordVersion };
export type Brand<Value, Name extends string> = Value & { readonly __brand: Name };

const UUID_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

/**
 * Parse a path segment into a uuid-shaped branded id, or nothing.
 *
 * These ids are stored in `uuid` columns, so a malformed one is not a lookup
 * that finds nothing — Postgres rejects the value while casting it, and the
 * route answers 500 for what is simply an id that cannot exist. The brand is
 * the caller's to name, exactly as the bare `as` casts this replaces did, but
 * now the value has been checked before it carries the name.
 *
 * `UnitId` and `ExecutionId` are deliberately not covered: both are text
 * columns, so any string is a legitimate lookup that finds nothing.
 */
export const parseUuidId = <Id extends string>(raw: string | undefined): Id | null =>
  raw !== undefined && UUID_PATTERN.test(raw) ? raw as Id : null;

export type WorkflowDefinitionId = Brand<string, "WorkflowDefinitionId">;
export type WorkflowRunId = Brand<string, "WorkflowRunId">;
export type StageInstanceId = Brand<string, "StageInstanceId">;
export type ArtifactId = Brand<string, "ArtifactId">;
export type ProjectId = Brand<string, "ProjectId">;
export type ExecutionId = Brand<string, "ExecutionId">;
export type RootWorkflowId = Brand<string, "RootWorkflowId">;
export type StageCoordinatorWorkflowId = Brand<string, "StageCoordinatorWorkflowId">;
export type UnitId = Brand<string, "UnitId">;
export type WaitId = Brand<string, "WaitId">;
export type RunUnitId = Brand<string, "RunUnitId">;
export type TaskOrderId = Brand<string, "TaskOrderId">;
export type ExecutorOperationId = Brand<string, "ExecutorOperationId">;
export type RunRecordVersion = Brand<number, "RunRecordVersion">;
export type OutputSlotVersion = Brand<number, "OutputSlotVersion">;
export type OutputCollectionKey = Brand<string, "OutputCollectionKey">;
export type InputFingerprint = Brand<string, "InputFingerprint">;
export type RunTransitionId = Brand<string, "RunTransitionId">;

/**
 * One attempt at an execution — the ID of the workflow running it. A rerun
 * forks that workflow under a new ID, so this changes per attempt while staying
 * stable across step retries and recovery of the same attempt. That is exactly
 * the identity an external executor session must be keyed on: the execution id
 * alone is shared by every attempt, so keying on it makes a rerun re-attach to
 * the session that already died.
 */
export type ExecutionAttemptId = Brand<string, "ExecutionAttemptId">;

export const executorOperationIdForWorkOrder = (id: TaskOrderId): ExecutorOperationId => id as unknown as ExecutorOperationId;

export type JsonPrimitive = string | number | boolean | null;
export type JsonValue = JsonPrimitive | readonly JsonValue[] | { readonly [key: string]: JsonValue };

/** Narrows parsed request bodies at the IO boundary; lives beside the type it guards. */
export const isJsonValue = (value: unknown): value is JsonValue => {
  if (value === null || typeof value === "string" || typeof value === "number" || typeof value === "boolean") return true;
  if (Array.isArray(value)) return value.every(isJsonValue);
  return typeof value === "object" && Object.values(value as object).every(isJsonValue);
};

export type Result<Value, ErrorValue> =
  | { readonly ok: true; readonly value: Value }
  | { readonly ok: false; readonly error: ErrorValue };

export const ok = <Value>(value: Value): Result<Value, never> => ({ ok: true, value });
export const err = <ErrorValue>(error: ErrorValue): Result<never, ErrorValue> => ({ ok: false, error });
/**
 * The ids `derive` mints — spec §13, moved verbatim from
 * `runtime/run-materialization.ts`. Determinism here is what makes replay
 * and duplicate-ask safety free: never introduce a random id anywhere in
 * the decision path.
